### feature:-1:mkmk ###
table GDEF {
 GlyphClassDef [A AE B C D Eth E F G H I J K L M N O OE P Thorn Q R S Germandbls T U V W X Y Z Q.ss01 a ae b c d eth e f g h i idotless jdotless k l m n o oe p thorn q r s germandbls t u v w x y z f.lig_comp alpha numero],# Base 
 [f_b.liga f_h.liga f_i.liga f_j.liga f_k.liga f_l.liga], # Liga 
 [dieresiscomb dotaccentcomb gravecomb acutecomb hungarumlautcomb caroncomb.alt circumflexcomb caroncomb brevecomb ringcomb tildecomb macroncomb commaturnedabovecomb commaaccentcomb cedillacomb ogonekcomb], # Mark 
 ;
 LigatureCaretByPos f_b.liga 431;
